-- Migration 329: Master Synchronisation of Billing API Customers and 92k Live Rate Cards
-- 1. Ensure columns and trigger setup
DROP TRIGGER IF EXISTS trg_customer_dc_id_sync ON customers;

ALTER TABLE customers ALTER COLUMN account_number TYPE VARCHAR(255);
ALTER TABLE customers ALTER COLUMN dc_customer_id TYPE VARCHAR(255);

CREATE OR REPLACE FUNCTION sync_customer_dc_id()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  NEW.dc_customer_id := NEW.account_number;
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_customer_dc_id_sync
BEFORE INSERT OR UPDATE OF account_number ON customers
FOR EACH ROW EXECUTE FUNCTION sync_customer_dc_id();

-- Ensure customer_rates table exists
CREATE TABLE IF NOT EXISTS customer_rates (
  id                SERIAL PRIMARY KEY,
  customer_id       UUID NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  courier_id        INT NOT NULL,
  courier_code      VARCHAR(50),
  courier_name      VARCHAR(100),
  service_id        INT NOT NULL,
  service_code      VARCHAR(100),
  service_name      VARCHAR(200),
  zone_id           INT NOT NULL,
  zone_name         VARCHAR(200),
  weight_class_id   INT NOT NULL,
  weight_class_name VARCHAR(200),
  price             NUMERIC(10,4) NOT NULL,
  UNIQUE (customer_id, service_id, zone_id, weight_class_id)
);

CREATE INDEX IF NOT EXISTS idx_customer_rates_customer ON customer_rates(customer_id);
CREATE INDEX IF NOT EXISTS idx_customer_rates_service  ON customer_rates(customer_id, service_id);

