        primary_email = COALESCE(NULLIF('cluckclickmarketing@gmail.com', ''), primary_email),
        phone_number = COALESCE(NULLIF('01617265969', ''), phone_number),
        address_line_1 = COALESCE(NULLIF('Unit 3', ''), address_line_1),
        address_line_2 = COALESCE(NULLIF('', ''), address_line_2),
        city = COALESCE(NULLIF('Heywood', ''), city),
        county = COALESCE(NULLIF('', ''), county),
        postcode = COALESCE(NULLIF('OL10 1ND', ''), postcode),
        country = COALESCE(NULLIF('United Kingdom', ''), country, 'United Kingdom'),
        billing_cycle = 'weekly',
        updated_at = NOW()
    WHERE id = v_cust_id;
  
  END IF;

  -- ── Customer: Eastern Square Ltd (MOOV-0228) ──
  SELECT id INTO v_cust_id FROM customers 
  WHERE dc_customer_id = 'MOOV-0228'
     OR account_number = 'MOOV-0228'
     OR LOWER(TRIM(business_name)) = LOWER(TRIM('Eastern Square Ltd'))
     OR LOWER(TRIM(business_name)) = LOWER(TRIM('Eastern Square Ltd'))
  LIMIT 1;

  IF v_cust_id IS NULL THEN
    SELECT id INTO v_cust_id FROM customers 
    WHERE REGEXP_REPLACE(LOWER(business_name), '(limited|ltd|plc|llc|uk|t/a|[^a-z0-9])', '', 'g') = 
          REGEXP_REPLACE(LOWER('Eastern Square Ltd'), '(limited|ltd|plc|llc|uk|t/a|[^a-z0-9])', '', 'g')
    ORDER BY LENGTH(business_name) ASC LIMIT 1;
  END IF;

  IF v_cust_id IS NOT NULL THEN
    -- Clear duplicate account_number from any other row
    UPDATE customers 
    SET account_number = 'MOS-' || SUBSTRING(id::TEXT, 1, 8)
    WHERE account_number = 'MOOV-0228'
      AND id != v_cust_id;

    UPDATE customers 
    SET dc_customer_id = NULL 
    WHERE dc_customer_id = 'MOOV-0228'
      AND id != v_cust_id;

    UPDATE customers 
    SET business_name = 'Eastern Square Ltd',
        account_number = 'MOOV-0228',
        dc_customer_id = 'MOOV-0228',
        primary_email = COALESCE(NULLIF('info@e-square.co.uk', ''), primary_email),
        phone_number = COALESCE(NULLIF('07500707791', ''), phone_number),
        address_line_1 = COALESCE(NULLIF('80 Brick Kiln Lane', ''), address_line_1),
        address_line_2 = COALESCE(NULLIF('STOKE-ON-TRENT', ''), address_line_2),
        city = COALESCE(NULLIF('Stoke-on-trent', ''), city),
        county = COALESCE(NULLIF('', ''), county),
        postcode = COALESCE(NULLIF('ST4 7BU', ''), postcode),
        country = COALESCE(NULLIF('United Kingdom', ''), country, 'United Kingdom'),
        billing_cycle = 'weekly',
        updated_at = NOW()
    WHERE id = v_cust_id;
  
  END IF;

  -- Ensure Europa PLC is explicitly set to 'Europa'
  UPDATE customers 
  SET business_name = 'Europa PLC',
      account_number = 'Europa',
      dc_customer_id = 'Europa',
      updated_at = NOW()
  WHERE LOWER(business_name) LIKE '%europa%';

  -- Ensure Hairbitz is explicitly set to 'HOF-0029'
  UPDATE customers 
  SET business_name = 'Hairbitz Ltd',
      account_number = 'HOF-0029',
      dc_customer_id = 'HOF-0029',
      updated_at = NOW()
  WHERE LOWER(business_name) LIKE '%hairbit%';

END $$;

