  v_c_id UUID;
BEGIN
  SELECT id INTO v_c_id FROM customers WHERE dc_customer_id = 'MOOV-0144' OR account_number = 'MOOV-0144' LIMIT 1;
  IF v_c_id IS NOT NULL THEN
    ON CONFLICT (customer_id, service_id, zone_id, weight_class_id)
    DO UPDATE SET 
      price = EXCLUDED.price,
      courier_code = EXCLUDED.courier_code,
      courier_name = EXCLUDED.courier_name,
      service_code = EXCLUDED.service_code,
      service_name = EXCLUDED.service_name,
      zone_name = EXCLUDED.zone_name,
      weight_class_name = EXCLUDED.weight_class_name;
  END IF;
END $$;

